<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use App\Models\{User,Guest,RoomType,Room,Reservation,MenuItem,RestaurantOrder,FolioCharge,Payment};
use Illuminate\Support\Str;
use App\Services\HotelService;
class HospitalityTest extends TestCase {
 use RefreshDatabase;
 private User $staff;private User $member;private Guest $guest;private Room $room;
 protected function setUp():void{parent::setUp();$this->staff=User::factory()->create(['role'=>'admin']);$this->guest=Guest::create(['name'=>'Sample Guest','email'=>'guest@example.com']);$this->member=User::factory()->create(['role'=>'guest','guest_id'=>$this->guest->id]);$t=RoomType::create(['name'=>'Standard','rate'=>1000,'capacity'=>2]);$this->room=Room::create(['number'=>'101','room_type_id'=>$t->id]);}
 private function book(array $extra=[]){$v=$extra;if(isset($v['guest_count'])){$v['adults']=$v['guest_count'];unset($v['guest_count']);}return $this->actingAs($this->staff)->postJson('/api/reservations',[...['guest_id'=>$this->guest->id,'room_type_id'=>$this->room->room_type_id,'arrival'=>today()->toDateString(),'departure'=>today()->addDay()->toDateString(),'adults'=>1,'children'=>0,'breakfast'=>'None','breakfast_pax'=>0],...$v]);}
 private function payment(int $id,float $amount=1000,?string $key=null){return $this->postJson('/api/reservations/'.$id.'/payments',['amount'=>$amount,'method'=>'Cash','posting_location'=>'Hotel Desk','idempotency_key'=>$key??(string)Str::uuid()]);}
 public function test_public_pages_and_catalog_render():void{$this->followingRedirects()->get('/')->assertOk();$this->followingRedirects()->get('/login')->assertOk();$this->followingRedirects()->get('/rooms')->assertOk();$this->getJson('/api/catalog')->assertOk()->assertJsonCount(1,'types');}
 public function test_guest_cannot_access_staff_endpoints():void{$this->actingAs($this->member)->getJson('/api/dashboard')->assertForbidden();$this->get('/staff')->assertForbidden();}
 public function test_unauthenticated_directory_is_blocked():void{$this->getJson('/api/directory/guests')->assertUnauthorized();}
 public function test_server_prices_booking_and_blocks_overlap():void{$r=$this->book(['amount'=>1])->assertCreated()->assertJsonPath('amount',1000)->json();$this->book()->assertUnprocessable();$this->assertDatabaseCount('reservations',1);}
 public function test_capacity_and_out_of_service_are_enforced():void{$this->book(['guest_count'=>3])->assertUnprocessable();$this->room->update(['out_of_service'=>true]);$this->book()->assertUnprocessable();}
 public function test_guest_reservation_uses_own_identity():void{$other=Guest::create(['name'=>'Other']);$this->actingAs($this->member)->postJson('/api/reservations',['guest_id'=>$other->id,'payer_guest_id'=>$other->id,'room_type_id'=>$this->room->room_type_id,'arrival'=>today()->toDateString(),'departure'=>today()->addDay()->toDateString(),'adults'=>1,'children'=>0,'breakfast'=>'None','breakfast_pax'=>0])->assertCreated()->assertJsonPath('guest_id',$this->guest->id)->assertJsonPath('payer_guest_id',$this->guest->id);}
 public function test_dirty_room_cannot_check_in():void{$r=$this->book()->json();$this->room->update(['housekeeping_status'=>'Dirty']);$this->putJson('/api/reservations/'.$r['id'].'/room',['room_id'=>$this->room->id]);$this->postJson('/api/reservations/'.$r['id'].'/check-in')->assertUnprocessable();}
 public function test_checkout_requires_settlement_and_marks_room_dirty():void{$r=$this->book()->json();$this->putJson('/api/reservations/'.$r['id'].'/room',['room_id'=>$this->room->id]);$this->postJson('/api/reservations/'.$r['id'].'/check-in')->assertOk();$this->postJson('/api/reservations/'.$r['id'].'/check-out',['overrideReason'=>'ignore'])->assertUnprocessable();$this->payment($r['id'])->assertSuccessful();$this->postJson('/api/reservations/'.$r['id'].'/check-out')->assertOk();$this->assertDatabaseHas('rooms',['id'=>$this->room->id,'housekeeping_status'=>'Dirty']);}
 public function test_payment_idempotency_and_overpayment():void{$r=$this->book()->json();$key=(string)Str::uuid();$this->payment($r['id'],500,$key)->assertSuccessful();$this->payment($r['id'],500,$key)->assertSuccessful();$this->assertDatabaseCount('payments',1);$this->payment($r['id'],1000)->assertUnprocessable();$this->payment($r['id'],400,$key)->assertConflict();}
 public function test_guest_cannot_read_another_folio():void{$r=$this->book()->json();$other=Guest::create(['name'=>'Other']);$u=User::factory()->create(['role'=>'guest','guest_id'=>$other->id]);$this->actingAs($u)->getJson('/api/reservations/'.$r['id'].'/folio')->assertForbidden();}
 public function test_restaurant_room_charge_posts_once():void{$r=$this->book()->json();$this->putJson('/api/reservations/'.$r['id'].'/room',['room_id'=>$this->room->id]);$this->postJson('/api/reservations/'.$r['id'].'/check-in')->assertOk();$m=MenuItem::create(['name'=>'Tea','category'=>'Drinks','price'=>50]);$o=$this->postJson('/api/orders',['items'=>[['menu_item_id'=>$m->id,'quantity'=>2]],'amount'=>1])->assertCreated()->json();$this->assertEquals(100,$o['amount']);$settle=['settlement'=>'Room','reservation_id'=>$r['id'],'idempotency_key'=>(string)Str::uuid()];$this->postJson('/api/orders/'.$o['id'].'/settle',$settle)->assertOk();$this->postJson('/api/orders/'.$o['id'].'/settle',$settle)->assertUnprocessable();$this->assertDatabaseCount('folio_charges',1);$this->getJson('/api/reservations/'.$r['id'].'/folio')->assertJsonPath('balance',1100);}
 public function test_cash_restaurant_requires_sufficient_cash():void{$this->actingAs($this->staff);$m=MenuItem::create(['name'=>'Tea','category'=>'Drinks','price'=>50]);$o=$this->postJson('/api/orders',['items'=>[['menu_item_id'=>$m->id,'quantity'=>1]]])->json();$v=['settlement'=>'Cash','cash_received'=>40,'idempotency_key'=>(string)Str::uuid()];$this->postJson('/api/orders/'.$o['id'].'/settle',$v)->assertUnprocessable();$v['cash_received']=100;$this->postJson('/api/orders/'.$o['id'].'/settle',$v)->assertOk()->assertJsonPath('change',50);$this->assertDatabaseCount('payments',1);}
 public function test_closed_stay_cannot_receive_room_charge():void{$r=$this->book()->json();Reservation::find($r['id'])->update(['status'=>'Checked-out']);$m=MenuItem::create(['name'=>'Tea','category'=>'Drinks','price'=>50]);$o=$this->postJson('/api/orders',['items'=>[['menu_item_id'=>$m->id,'quantity'=>1]]])->json();$this->postJson('/api/orders/'.$o['id'].'/settle',['settlement'=>'Room','reservation_id'=>$r['id'],'idempotency_key'=>(string)Str::uuid()])->assertUnprocessable();}
 public function test_unique_normalized_guest_contacts():void{$this->postJson('/api/register',['name'=>'A','email'=>'unique@example.com','phone'=>'09171234567','password'=>'longpassword12','password_confirmation'=>'longpassword12'])->assertCreated();$this->postJson('/api/register',['name'=>'B','email'=>'UNIQUE@example.com','phone'=>'+63 917 123 4567','password'=>'longpassword12','password_confirmation'=>'longpassword12'])->assertUnprocessable();}
 public function test_cancellation_policy_and_refund_credit():void{$r=$this->book(['arrival'=>today()->addDay()->toDateString(),'departure'=>today()->addDays(2)->toDateString()])->json();$this->payment($r['id'])->assertSuccessful();$this->postJson('/api/reservations/'.$r['id'].'/cancel')->assertOk()->assertJsonPath('balance',-500);$this->postJson('/api/reservations/'.$r['id'].'/refunds',['amount'=>500,'reason'=>'Cancellation credit','idempotency_key'=>(string)Str::uuid()])->assertCreated();$this->getJson('/api/reservations/'.$r['id'].'/folio')->assertJsonPath('balance',0);}
 public function test_early_cancellation_is_free():void{$r=$this->book(['arrival'=>today()->addDays(4)->toDateString(),'departure'=>today()->addDays(5)->toDateString()])->json();$this->postJson('/api/reservations/'.$r['id'].'/cancel')->assertOk()->assertJsonPath('reservation.amount',0);}
 public function test_inhouse_filter_uses_occupants():void{$occupant=Guest::create(['name'=>'Occupant']);$r=$this->book(['occupant_ids'=>[$occupant->id]])->json();$this->putJson('/api/reservations/'.$r['id'].'/room',['room_id'=>$this->room->id]);$this->postJson('/api/reservations/'.$r['id'].'/check-in')->assertOk();$this->getJson('/api/directory/guests?in_house=1')->assertJsonCount(1)->assertJsonPath('0.name','Occupant');$this->getJson('/api/directory/guests')->assertJsonCount(2);}
 public function test_non_admin_cannot_manage_accounts():void{$u=User::factory()->create(['role'=>'frontdesk']);$this->actingAs($u)->getJson('/api/directory/employees')->assertForbidden();}
 public function test_inactive_account_is_blocked():void{$this->member->update(['active'=>false]);$this->actingAs($this->member)->getJson('/api/reservations')->assertForbidden();}
 public function test_kiosk_verification_and_one_time_checkin():void{$this->markTestSkipped('Legacy kiosk/loyalty flow is retired from the revised staff-assigned room and configurable-discount scope.');$r=$this->book()->json();$token=$this->postJson('/api/reservations/'.$r['id'].'/kiosk-token')->assertOk()->json();$this->postJson('/api/logout')->assertOk();$this->postJson('/api/kiosk/verify',['code'=>$r['code'],'verification_code'=>$token['verification_code']])->assertOk();$this->withSession(['kiosk_scan_review'=>true])->postJson('/api/kiosk/complete',['name'=>$this->guest->name,'reviewed'=>true])->assertOk();$this->postJson('/api/kiosk/verify',['code'=>$r['code'],'verification_code'=>$token['verification_code']])->assertUnprocessable();}
 public function test_report_room_charge_is_not_cash_collection():void{$r=$this->book()->json();FolioCharge::create(['reservation_id'=>$r['id'],'description'=>'Dining','amount'=>100]);$this->getJson('/api/reports')->assertOk()->assertJsonPath('additional_charges',100)->assertJsonPath('collections',0);}

 public function test_ocr_extracts_supported_sample_and_removes_capture():void{$this->markTestSkipped('Legacy kiosk/loyalty flow is retired from the revised staff-assigned room and configurable-discount scope.');$r=$this->book()->json();$token=$this->postJson('/api/reservations/'.$r['id'].'/kiosk-token')->json();$this->postJson('/api/kiosk/verify',['code'=>$r['code'],'verification_code'=>$token['verification_code']])->assertOk();$file=new \Illuminate\Http\UploadedFile(base_path('tests/sample-id.png'),'sample-id.png','image/png',null,true);$this->post('/api/kiosk/scan',['image'=>$file],['Accept'=>'application/json'])->assertOk()->assertJsonPath('fields.name','Sample Guest')->assertJsonPath('fields.birth_date','2000-01-15');$files=\Illuminate\Support\Facades\Storage::disk('local')->files('ocr-tmp');$this->assertCount(0,$files);$this->postJson('/api/kiosk/complete',['name'=>'Sample Guest','reviewed'=>true])->assertOk();}
 public function test_kiosk_requires_a_completed_scan():void{$this->markTestSkipped('Legacy kiosk/loyalty flow is retired from the revised staff-assigned room and configurable-discount scope.');$r=$this->book()->json();$t=$this->postJson('/api/reservations/'.$r['id'].'/kiosk-token')->json();$this->postJson('/api/kiosk/verify',['code'=>$r['code'],'verification_code'=>$t['verification_code']])->assertOk();$this->postJson('/api/kiosk/complete',['name'=>'Sample Guest','reviewed'=>true])->assertUnprocessable();}
 public function test_points_redemption_is_validated_and_deducted_once():void{$this->markTestSkipped('Legacy kiosk/loyalty flow is retired from the revised staff-assigned room and configurable-discount scope.');$this->room->type->update(['points_per_night'=>200]);$this->member->update(['points'=>500]);$this->actingAs($this->member)->postJson('/api/reservations',['room_type_id'=>$this->room->room_type_id,'arrival'=>today()->toDateString(),'departure'=>today()->addDay()->toDateString(),'adults'=>1,'children'=>0,'breakfast'=>'None','breakfast_pax'=>0,'pay_with_points'=>true])->assertCreated()->assertJsonPath('amount',0)->assertJsonPath('points_redeemed',200);$this->assertSame(300,$this->member->fresh()->points);$this->actingAs($this->member)->postJson('/api/reservations',['room_type_id'=>$this->room->room_type_id,'arrival'=>today()->toDateString(),'departure'=>today()->addDay()->toDateString(),'adults'=>1,'children'=>0,'breakfast'=>'None','breakfast_pax'=>0,'pay_with_points'=>true])->assertUnprocessable();$this->assertSame(300,$this->member->fresh()->points);}
 public function test_member_discount_uses_server_points():void{$this->markTestSkipped('Legacy kiosk/loyalty flow is retired from the revised staff-assigned room and configurable-discount scope.');$this->member->update(['points'=>500]);$this->actingAs($this->member)->postJson('/api/reservations',['room_type_id'=>$this->room->room_type_id,'arrival'=>today()->toDateString(),'departure'=>today()->addDay()->toDateString(),'adults'=>1,'children'=>0,'breakfast'=>'None','breakfast_pax'=>0,'amount'=>1])->assertCreated()->assertJsonPath('amount',800);}
 public function test_statement_is_owned_and_printable():void{$r=$this->book()->json();$this->get('/reservations/'.$r['id'].'/receipt')->assertOk()->assertSee($r['code']);$g=Guest::create(['name'=>'Other']);$u=User::factory()->create(['guest_id'=>$g->id]);$this->actingAs($u)->get('/reservations/'.$r['id'].'/receipt')->assertForbidden();}
 public function test_linked_account_contact_edit_enforces_uniqueness():void{$this->member->update(['phone'=>'+639171234567']);$other=User::factory()->create(['phone'=>'+639181234567']);$this->actingAs($this->staff)->putJson('/api/directory/guests/'.$this->guest->id,['name'=>'Changed','email'=>$other->email,'phone'=>'+639181234567'])->assertUnprocessable();$this->assertSame('Sample Guest',$this->guest->fresh()->name);}
}
